//! Phoenix Channels gateway for ice-rpc services.
//!
//! The gateway is a [`trillium_websockets::WebSocketHandler`] mounted on the
//! same trillium server as the HTTP gateway. Each service is its own topic: a
//! browser joins `socket.channel("Database", params)` and pushes `call`,
//! `stream` or `cancel`; the gateway dispatches to the JSON view generated by
//! `#[service]` and pushes the resulting events back.
//!
//! The Phoenix envelope lives in [`crate::phoenix`], directly on
//! `trillium-websockets` 0.9: the maintained `trillium-channels` 0.4.0 still
//! depends on `trillium-websockets` 0.7, which drops the query string of the
//! upgrade request. That query carries `vsn=2.0.0`, so the channel crate sees
//! an empty version and parses every modern Phoenix client message as V1.
//!
//! # Wire contract
//!
//! Each service is its own topic, named after the service: the client joins
//! `socket.channel("Database", params)`. It then pushes:
//!
//! | Event | Payload | Answer |
//! |---|---|---|
//! | `call` | `{ method, args }` | one `phx_reply` |
//! | `stream` | `{ method, args }` | one `phx_reply` ack, then events |
//! | `cancel` | `{ ref }` | one `phx_reply` ack |
//!
//! A `call` reply is `{"status":"ok","response":{"kind":"value","data":…}}`,
//! `{"kind":"nothing"}` or `{"kind":"accepted","delivered":…}`. A failure is
//! `{"status":"error","response":{"kind":"E_…","message":…}}`.
//!
//! A `stream` is acknowledged immediately so a long stream does not trip the
//! Phoenix push timeout, then pushes `next`, `complete`, `error` or `accepted`
//! events carrying the push's `ref`. The Phoenix `ref` is the correlation id;
//! the client does not invent one.
//!
//! # Transport
//!
//! The Phoenix JavaScript client appends `/websocket` to the socket endpoint and
//! uses `vsn=2.0.0` (the array framing). The gateway routes
//! `{path}/websocket` (default `/socket/websocket`) to the Phoenix handler and
//! mounts the REST gateway on every other path. The client must use the
//! WebSocket transport: the long-poll fallback is not implemented.

use std::borrow::Cow;
use std::collections::HashMap;
use std::net::IpAddr;
use std::sync::{Arc, Mutex};

use serde_json::{Value, json};
use trillium::{Conn, Handler, Headers, Info, Upgrade};
use trillium_websockets::tungstenite::protocol::CloseFrame;
use trillium_websockets::{Message, WebSocketConn, WebSocketHandler, websocket};

use crate::CancellationToken;
use crate::gateway_registry::JsonInvokerRegistry;
use crate::json::{
    JsonCallError, JsonEventSink, JsonInvokerFactory, JsonOutcome, JsonStreamEvent, ReadMode,
};
use crate::phoenix::{PhoenixFrame, PhoenixVersion, encode, version_from_query};

/// Configuration of the Phoenix Channels gateway.
#[non_exhaustive]
#[derive(Clone)]
pub struct ChannelsGatewayConfig {
    /// Phoenix endpoint path, without the `/websocket` suffix.
    ///
    /// Defaults to `/socket`. The gateway routes `{path}/websocket` because the
    /// Phoenix JavaScript client appends that suffix itself.
    pub path: Cow<'static, str>,
    /// Exact origins allowed to join. Empty means any origin, logged at startup.
    pub allowed_origins: Vec<String>,
    /// Maximum number of calls in flight on one connection. Defaults to 32.
    pub max_calls_per_channel: usize,
    /// Capacity of the bounded channel between the service and the socket.
    ///
    /// A slow client applies backpressure to the service through this channel.
    /// Defaults to 16.
    pub stream_buffer: usize,
    /// Optional join authorizer.
    ///
    /// When absent, the gateway accepts every join that matches the origin
    /// allowlist. Authentication in front of the gateway is then the
    /// deployment's responsibility.
    pub authorizer: Option<Arc<dyn ChannelsAuthorizer>>,
}

impl ChannelsGatewayConfig {
    /// Builds the default configuration.
    #[must_use]
    pub fn new() -> Self {
        Self {
            path: Cow::Borrowed("/socket"),
            allowed_origins: Vec::new(),
            max_calls_per_channel: 32,
            stream_buffer: 16,
            authorizer: None,
        }
    }

    /// Returns the WebSocket route the Phoenix client actually requests.
    fn websocket_path(&self) -> String {
        format!("{}/websocket", self.path.trim_end_matches('/'))
    }
}

impl Default for ChannelsGatewayConfig {
    fn default() -> Self {
        Self::new()
    }
}

/// Decides whether a Phoenix channel join is allowed.
pub trait ChannelsAuthorizer: Send + Sync + 'static {
    /// Returns `Ok(())` to accept the join, or a client-facing reason to refuse.
    ///
    /// The reason is sent in the `phx_reply` error as `E_UNAUTHORIZED`.
    fn authorize_join(&self, context: &JoinContext<'_>) -> Result<(), String>;
}

/// Read-only view of the handshake and join parameters offered to an authorizer.
#[non_exhaustive]
pub struct JoinContext<'a> {
    headers: &'a Headers,
    params: &'a Value,
    peer_addr: Option<IpAddr>,
    service: &'a str,
}

impl<'a> JoinContext<'a> {
    /// Returns one HTTP header, case-insensitively.
    #[must_use]
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers.get_str(name)
    }

    /// Returns one join parameter, typically `token`.
    #[must_use]
    pub fn param(&self, name: &str) -> Option<&'a Value> {
        self.params.get(name)
    }

    /// Returns the peer address.
    #[must_use]
    pub fn peer_addr(&self) -> Option<IpAddr> {
        self.peer_addr
    }

    /// Returns the service named by the joined topic.
    #[must_use]
    pub fn service(&self) -> &'a str {
        self.service
    }
}

/// Builds the Phoenix Channels handler for custom trillium composition.
///
/// The returned handler upgrades `{path}/websocket` and serves the configured
/// topic. Most applications use [`start_channels_server`] instead, which also
/// mounts the REST gateway on the same listener.
pub fn channels_handler(
    config: ChannelsGatewayConfig,
    factories: HashMap<&'static str, JsonInvokerFactory>,
) -> impl trillium::Handler {
    websocket(ChannelsHandler::new(
        config,
        JsonInvokerRegistry::new(factories),
    ))
}

/// Starts REST and Phoenix Channels on the same trillium server.
///
/// The server binds to `127.0.0.1:{port}` and stops when
/// [`global_cancel_token`](crate::global_cancel_token) is cancelled.
pub async fn start_channels_server(
    port: u16,
    factories: HashMap<&'static str, JsonInvokerFactory>,
) {
    start_channels_server_with_config(port, ChannelsGatewayConfig::new(), factories).await;
}

/// Starts REST and Phoenix Channels with an explicit gateway configuration.
///
/// The REST routes and the Phoenix handler share one invoker registry, so a
/// service's JSON view is created once whatever transport calls it.
pub async fn start_channels_server_with_config(
    port: u16,
    config: ChannelsGatewayConfig,
    factories: HashMap<&'static str, JsonInvokerFactory>,
) {
    let mut topics: Vec<&'static str> = factories.keys().copied().collect();
    topics.sort_unstable();
    let registry = JsonInvokerRegistry::new(factories);
    let http = crate::http_gateway::http_handler(registry.clone());
    let channels = websocket(ChannelsHandler::new(config.clone(), registry));
    let socket_path = config.websocket_path();
    let handler = RpcGateway {
        http,
        channels,
        socket_path: socket_path.clone(),
    };

    log::info!(
        "🔌 ice-rpc Phoenix Channels gateway mounted at ws://127.0.0.1:{}{}",
        port,
        socket_path
    );
    log::info!(
        "   endpoint: '{}', topics: {}",
        config.path,
        topics.join(", ")
    );
    log::info!(
        "   client: new Socket(\"{}\", {{ transport: WebSocket }})",
        config.path
    );
    if config.allowed_origins.is_empty() {
        log::warn!("Phoenix Channels: no Origin allowlist configured, every origin is accepted");
    }

    crate::http_gateway::serve_trillium(port, handler).await;
    log::info!("Phoenix Channels server stopped.");
}

/// Routes the WebSocket path to the channel handler and everything else to REST.
///
/// The REST handler halts every response, so the WebSocket path must be
/// selected before it runs. The upgrade methods are forwarded because the
/// channel handler is the only one that claims a WebSocket upgrade.
struct RpcGateway<Http, Channels> {
    http: Http,
    channels: Channels,
    socket_path: String,
}

impl<Http, Channels> Handler for RpcGateway<Http, Channels>
where
    Http: Handler,
    Channels: Handler,
{
    async fn run(&self, conn: Conn) -> Conn {
        if conn.path() == self.socket_path {
            self.channels.run(conn).await
        } else {
            self.http.run(conn).await
        }
    }

    async fn init(&mut self, info: &mut Info) {
        self.http.init(info).await;
        self.channels.init(info).await;
    }

    async fn before_send(&self, conn: Conn) -> Conn {
        let conn = self.channels.before_send(conn).await;
        self.http.before_send(conn).await
    }

    fn has_upgrade(&self, upgrade: &Upgrade) -> bool {
        self.channels.has_upgrade(upgrade)
    }

    async fn upgrade(&self, upgrade: Upgrade) {
        self.channels.upgrade(upgrade).await;
    }
}

/// One Phoenix channel handler, shared by every connection.
struct ChannelsHandler {
    config: ChannelsGatewayConfig,
    registry: JsonInvokerRegistry,
}

impl ChannelsHandler {
    fn new(config: ChannelsGatewayConfig, registry: JsonInvokerRegistry) -> Self {
        Self { config, registry }
    }

    async fn join(&self, conn: &WebSocketConn, state: Arc<ConnectionState>, frame: PhoenixFrame) {
        if frame.topic == RESERVED_TOPIC {
            state
                .reply_error(&frame, E_UNKNOWN_TOPIC, "the `phoenix` topic is reserved")
                .await;
            return;
        }

        if !self.registry.has_service(&frame.topic) {
            let message = format!("unknown service '{}'", frame.topic);
            state.reply_error(&frame, E_UNKNOWN_SERVICE, &message).await;
            return;
        }

        if !self.config.allowed_origins.is_empty()
            && let Some(origin) = conn.headers().get_str("origin")
            && !origin_allowed(origin, &self.config.allowed_origins)
        {
            state
                .reply_error(&frame, E_UNAUTHORIZED, "origin not allowed")
                .await;
            return;
        }

        if let Some(authorizer) = &self.config.authorizer {
            let authorization = {
                let context = JoinContext {
                    headers: conn.headers(),
                    params: &frame.payload,
                    peer_addr: conn.peer_ip(),
                    service: &frame.topic,
                };
                authorizer.authorize_join(&context)
            };
            if let Err(reason) = authorization {
                state.reply_error(&frame, E_UNAUTHORIZED, &reason).await;
                return;
            }
        }

        state.join(&frame.topic);
        state
            .reply(
                &frame,
                "ok",
                &json!({ "protocol": 1, "service": &frame.topic }),
            )
            .await;
    }

    async fn handle_call(&self, state: Arc<ConnectionState>, service: String, frame: PhoenixFrame) {
        let request = match CallRequest::parse(&frame.payload) {
            Ok(request) => request,
            Err(message) => {
                state.reply_error(&frame, E_INVALID_ARGS, &message).await;
                return;
            }
        };
        let Some(reference) = frame.reference.clone() else {
            state
                .reply_error(&frame, E_INVALID_REF, "the push must carry a Phoenix ref")
                .await;
            return;
        };
        if !valid_ref(&reference) {
            state
                .reply_error(
                    &frame,
                    E_INVALID_REF,
                    "ref must be 1..=64 bytes of [A-Za-z0-9._:-]",
                )
                .await;
            return;
        }
        let Some(invoker) = self.registry.get_or_create(&service).await else {
            let message = format!("unknown service '{service}'");
            state.reply_error(&frame, E_UNKNOWN_SERVICE, &message).await;
            return;
        };
        let token = match state.admit(&service, &reference) {
            Ok(token) => token,
            Err(AdmissionError::NotJoined) => {
                state
                    .reply_error(&frame, E_NOT_JOINED, "join the service topic first")
                    .await;
                return;
            }
            Err(AdmissionError::Limit) => {
                let message = format!(
                    "{} calls already await an answer on this connection",
                    self.config.max_calls_per_channel
                );
                state.reply_error(&frame, E_LIMIT, &message).await;
                return;
            }
            Err(AdmissionError::Duplicate) => {
                state
                    .reply_error(&frame, E_DUPLICATE_REF, "ref is already in flight")
                    .await;
                return;
            }
        };

        let method = request.method;
        let args = request.args;
        crate::rt::spawn(async move {
            let cancel = token;
            let call = invoker.invoke_json(&method, args, ReadMode::First);
            let cancelled = async move {
                cancel.cancelled().await;
                None::<Result<JsonOutcome, JsonCallError>>
            };
            match futures_lite::future::or(call, cancelled).await {
                Some(Ok(outcome)) => {
                    state.reply_outcome(&frame, outcome).await;
                }
                Some(Err(error)) => {
                    state.reply_call_error(&frame, &error).await;
                }
                None => {
                    state
                        .reply_error(&frame, E_CANCELLED, "the call was cancelled")
                        .await;
                }
            }
            state.finish(&service, &reference);
        });
    }

    async fn handle_stream(
        &self,
        state: Arc<ConnectionState>,
        service: String,
        frame: PhoenixFrame,
    ) {
        let request = match CallRequest::parse(&frame.payload) {
            Ok(request) => request,
            Err(message) => {
                state.reply_error(&frame, E_INVALID_ARGS, &message).await;
                return;
            }
        };
        let Some(reference) = frame.reference.clone() else {
            state
                .reply_error(&frame, E_INVALID_REF, "the push must carry a Phoenix ref")
                .await;
            return;
        };
        if !valid_ref(&reference) {
            state
                .reply_error(
                    &frame,
                    E_INVALID_REF,
                    "ref must be 1..=64 bytes of [A-Za-z0-9._:-]",
                )
                .await;
            return;
        }
        let Some(invoker) = self.registry.get_or_create(&service).await else {
            let message = format!("unknown service '{service}'");
            state.reply_error(&frame, E_UNKNOWN_SERVICE, &message).await;
            return;
        };
        let token = match state.admit(&service, &reference) {
            Ok(token) => token,
            Err(AdmissionError::NotJoined) => {
                state
                    .reply_error(&frame, E_NOT_JOINED, "join the service topic first")
                    .await;
                return;
            }
            Err(AdmissionError::Limit) => {
                let message = format!(
                    "{} calls already await an answer on this connection",
                    self.config.max_calls_per_channel
                );
                state.reply_error(&frame, E_LIMIT, &message).await;
                return;
            }
            Err(AdmissionError::Duplicate) => {
                state
                    .reply_error(&frame, E_DUPLICATE_REF, "ref is already in flight")
                    .await;
                return;
            }
        };

        let method = request.method;
        let args = request.args;
        let (sink, receiver) = JsonEventSink::bounded(self.config.stream_buffer);

        // Acknowledge before the first event so a long stream does not trip the
        // Phoenix push timeout.
        state
            .reply(&frame, "ok", &json!({ "ref": &reference }))
            .await;

        let join_ref = frame.join_ref.clone();
        let topic = frame.topic.clone();
        let state_for_task = state.clone();
        crate::rt::spawn(async move {
            let cancel = token.clone();
            let call = futures_lite::future::or(
                invoker.invoke_json_stream(&method, args, sink),
                async move {
                    cancel.cancelled().await;
                    None
                },
            );

            let state_for_forward = state_for_task.clone();
            let join_ref_for_forward = join_ref.clone();
            let topic_for_forward = topic.clone();
            let reference_for_forward = reference.clone();
            let forward = async move {
                while let Ok(stream_event) = receiver.recv().await {
                    match stream_event {
                        JsonStreamEvent::Next(data) => {
                            state_for_forward
                                .push(
                                    join_ref_for_forward.as_deref(),
                                    &topic_for_forward,
                                    "next",
                                    &json!({ "ref": &reference_for_forward, "data": data }),
                                )
                                .await;
                        }
                        JsonStreamEvent::Complete => {
                            state_for_forward
                                .push(
                                    join_ref_for_forward.as_deref(),
                                    &topic_for_forward,
                                    "complete",
                                    &json!({ "ref": &reference_for_forward }),
                                )
                                .await;
                            break;
                        }
                        JsonStreamEvent::Accepted { delivered } => {
                            state_for_forward
                                .push(
                                    join_ref_for_forward.as_deref(),
                                    &topic_for_forward,
                                    "accepted",
                                    &json!({ "ref": &reference_for_forward, "delivered": delivered }),
                                )
                                .await;
                            break;
                        }
                        JsonStreamEvent::Failed(error) => {
                            send_stream_error(
                                &state_for_forward,
                                join_ref_for_forward.as_deref(),
                                &topic_for_forward,
                                &reference_for_forward,
                                &error,
                            )
                            .await;
                            break;
                        }
                    }
                }
            };

            let (result, ()) = futures_lite::future::zip(call, forward).await;
            if result.is_none() {
                if token.is_cancelled() {
                    let _ = state_for_task
                        .push(
                            join_ref.as_deref(),
                            &topic,
                            "complete",
                            &json!({ "ref": &reference }),
                        )
                        .await;
                } else {
                    send_stream_error_code(
                        &state_for_task,
                        join_ref.as_deref(),
                        &topic,
                        &reference,
                        E_UNKNOWN_METHOD,
                        "the service has no such method",
                    )
                    .await;
                }
            }
            state_for_task.finish(&service, &reference);
        });
    }

    async fn handle_cancel(&self, state: Arc<ConnectionState>, service: &str, frame: PhoenixFrame) {
        let Some(reference) = frame.payload.get("ref").and_then(Value::as_str) else {
            state
                .reply_error(&frame, E_INVALID_ARGS, "cancel requires a ref")
                .await;
            return;
        };
        if !valid_ref(reference) {
            state
                .reply_error(
                    &frame,
                    E_INVALID_REF,
                    "ref must be 1..=64 bytes of [A-Za-z0-9._:-]",
                )
                .await;
            return;
        }
        state.cancel(service, reference);
        state.reply(&frame, "ok", &json!({})).await;
    }
}

impl WebSocketHandler for ChannelsHandler {
    type OutboundStream = async_channel::Receiver<Message>;

    async fn connect(
        &self,
        mut conn: WebSocketConn,
    ) -> Option<(WebSocketConn, Self::OutboundStream)> {
        let version = version_from_query(conn.querystring());
        let (state, receiver) = ConnectionState::new(
            self.config.max_calls_per_channel,
            self.config.stream_buffer,
            version,
        );
        conn.insert_state(state);
        Some((conn, receiver))
    }

    async fn inbound(&self, message: Message, conn: &mut WebSocketConn) {
        let Ok(text) = message.to_text() else {
            log::debug!("Phoenix Channels: ignoring a non-text frame");
            return;
        };
        let Some(frame) = PhoenixFrame::parse(text) else {
            log::warn!("Phoenix Channels: ignoring an invalid Phoenix frame");
            return;
        };
        let Some(state) = conn.state::<Arc<ConnectionState>>().cloned() else {
            log::error!("Phoenix Channels: connection has no call table");
            return;
        };

        match (frame.topic.as_str(), frame.event.as_str()) {
            ("phoenix", "heartbeat") => {
                state.reply(&frame, "ok", &json!({})).await;
            }
            (_, "phx_join") => self.join(conn, state, frame).await,
            (topic, "phx_leave") => {
                state.leave(topic);
                state.reply(&frame, "ok", &json!({})).await;
            }
            (topic, event @ ("call" | "stream" | "cancel")) => {
                if !state.is_joined(topic) {
                    state
                        .reply_error(&frame, E_NOT_JOINED, "join the service topic first")
                        .await;
                    return;
                }
                let service = topic.to_string();
                match event {
                    "call" => self.handle_call(state, service, frame).await,
                    "stream" => self.handle_stream(state, service, frame).await,
                    _ => self.handle_cancel(state, &service, frame).await,
                }
            }
            (topic, event) => {
                let message = format!("unexpected event '{event}' on topic '{topic}'");
                state.reply_error(&frame, E_INVALID_ARGS, &message).await;
            }
        }
    }

    async fn disconnect(&self, conn: &mut WebSocketConn, _close_frame: Option<CloseFrame>) {
        if let Some(state) = conn.state::<Arc<ConnectionState>>().cloned() {
            state.shutdown();
        }
    }
}

/// Calls in flight on one joined service topic.
#[derive(Default)]
struct TopicState {
    calls: HashMap<String, CancellationToken>,
}

/// The service topics joined on one WebSocket connection, and its outbound frames.
struct ConnectionState {
    topics: Mutex<HashMap<String, TopicState>>,
    out: async_channel::Sender<Message>,
    max_calls: usize,
    version: PhoenixVersion,
}

impl ConnectionState {
    fn new(
        max_calls: usize,
        capacity: usize,
        version: PhoenixVersion,
    ) -> (Arc<Self>, async_channel::Receiver<Message>) {
        let (out, receiver) = async_channel::bounded(capacity.max(1));
        (
            Arc::new(Self {
                topics: Mutex::new(HashMap::new()),
                out,
                max_calls: max_calls.max(1),
                version,
            }),
            receiver,
        )
    }

    /// Marks `topic` as joined, cancelling calls left by a previous join.
    fn join(&self, topic: &str) {
        let mut topics = self.lock();
        if let Some(previous) = topics.insert(topic.to_string(), TopicState::default()) {
            for (_, token) in previous.calls {
                token.cancel();
            }
        }
    }

    /// Leaves `topic`, cancelling every call in flight on it.
    fn leave(&self, topic: &str) {
        let removed = self.lock().remove(topic);
        if let Some(previous) = removed {
            for (_, token) in previous.calls {
                token.cancel();
            }
        }
    }

    fn is_joined(&self, topic: &str) -> bool {
        self.lock().contains_key(topic)
    }

    fn admit(&self, topic: &str, id: &str) -> Result<CancellationToken, AdmissionError> {
        let mut topics = self.lock();
        let Some(state) = topics.get_mut(topic) else {
            return Err(AdmissionError::NotJoined);
        };
        if state.calls.len() >= self.max_calls {
            return Err(AdmissionError::Limit);
        }
        if state.calls.contains_key(id) {
            return Err(AdmissionError::Duplicate);
        }
        let token = CancellationToken::new();
        state.calls.insert(id.to_string(), token.clone());
        Ok(token)
    }

    fn finish(&self, topic: &str, id: &str) {
        let mut topics = self.lock();
        if let Some(state) = topics.get_mut(topic) {
            state.calls.remove(id);
        }
    }

    fn cancel(&self, topic: &str, id: &str) {
        let mut topics = self.lock();
        let token = topics
            .get_mut(topic)
            .and_then(|state| state.calls.remove(id));
        drop(topics);
        if let Some(token) = token {
            token.cancel();
        }
    }

    fn shutdown(&self) {
        let mut topics = self.lock();
        for (_, state) in topics.drain() {
            for (_, token) in state.calls {
                token.cancel();
            }
        }
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, HashMap<String, TopicState>> {
        self.topics
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    async fn send_frame(
        &self,
        join_ref: Option<&str>,
        reference: Option<&str>,
        topic: &str,
        event: &str,
        payload: &Value,
    ) -> bool {
        let frame = encode(self.version, join_ref, reference, topic, event, payload);
        self.out.send(Message::text(frame)).await.is_ok()
    }

    async fn reply(&self, frame: &PhoenixFrame, status: &str, response: &Value) -> bool {
        self.out
            .send(Message::text(frame.reply(self.version, status, response)))
            .await
            .is_ok()
    }

    async fn reply_error(&self, frame: &PhoenixFrame, kind: &str, message: &str) -> bool {
        self.reply(frame, "error", &json!({ "kind": kind, "message": message }))
            .await
    }

    async fn reply_call_error(&self, frame: &PhoenixFrame, error: &JsonCallError) -> bool {
        let (kind, message) = map_call_error(error);
        self.reply_error(frame, kind, message).await
    }

    async fn reply_outcome(&self, frame: &PhoenixFrame, outcome: JsonOutcome) -> bool {
        match outcome {
            JsonOutcome::Value(value) => {
                self.reply(frame, "ok", &json!({ "kind": "value", "data": value }))
                    .await
            }
            JsonOutcome::Nothing => self.reply(frame, "ok", &json!({ "kind": "nothing" })).await,
            JsonOutcome::Accepted { delivered } => {
                self.reply(
                    frame,
                    "ok",
                    &json!({ "kind": "accepted", "delivered": delivered }),
                )
                .await
            }
        }
    }

    async fn push(
        &self,
        join_ref: Option<&str>,
        topic: &str,
        event: &str,
        payload: &Value,
    ) -> bool {
        self.send_frame(join_ref, None, topic, event, payload).await
    }
}

/// Why a call could not be admitted to a topic's call table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AdmissionError {
    NotJoined,
    Limit,
    Duplicate,
}

/// The payload of a `call` or `stream` push.
///
/// The service is named by the topic and the correlation id by the Phoenix
/// `ref`, so the payload only carries the method and its arguments.
#[derive(serde::Deserialize)]
struct CallRequest {
    method: String,
    #[serde(default)]
    args: Value,
}

impl CallRequest {
    /// Parses and validates the payload of a `call` or `stream` push.
    fn parse(payload: &Value) -> Result<Self, String> {
        let request: Self = serde_json::from_value(payload.clone())
            .map_err(|error| format!("invalid call payload: {error}"))?;
        if request.method.is_empty() {
            return Err("method is required".to_string());
        }
        Ok(request)
    }
}

/// Checks the Phoenix reference accepted on the wire.
fn valid_ref(reference: &str) -> bool {
    !reference.is_empty()
        && reference.len() <= 64
        && reference
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b':' | b'-'))
}

/// Checks an origin against the exact-match allowlist.
fn origin_allowed(origin: &str, allowed: &[String]) -> bool {
    allowed.iter().any(|candidate| candidate == origin)
}

/// Maps the JSON contract error onto the gateway's stable code.
fn map_call_error(error: &JsonCallError) -> (&'static str, &str) {
    match error {
        JsonCallError::InvalidArgs(message) => (E_INVALID_ARGS, message),
        JsonCallError::Business(message) => (E_BUSINESS, message),
        JsonCallError::Transport(message) => (E_TRANSPORT, message),
    }
}

/// Pushes a terminal error of a streamed call.
async fn send_stream_error(
    state: &ConnectionState,
    join_ref: Option<&str>,
    topic: &str,
    reference: &str,
    error: &JsonCallError,
) {
    let (kind, message) = map_call_error(error);
    send_stream_error_code(state, join_ref, topic, reference, kind, message).await;
}

/// Pushes a terminal error of a streamed call, with an explicit code.
async fn send_stream_error_code(
    state: &ConnectionState,
    join_ref: Option<&str>,
    topic: &str,
    reference: &str,
    kind: &str,
    message: &str,
) {
    state
        .push(
            join_ref,
            topic,
            "error",
            &json!({ "ref": reference, "kind": kind, "message": message }),
        )
        .await;
}

/// Phoenix reserves this topic for its heartbeat.
const RESERVED_TOPIC: &str = "phoenix";

const E_UNAUTHORIZED: &str = "E_UNAUTHORIZED";
const E_UNKNOWN_TOPIC: &str = "E_UNKNOWN_TOPIC";
const E_UNKNOWN_SERVICE: &str = "E_UNKNOWN_SERVICE";
const E_UNKNOWN_METHOD: &str = "E_UNKNOWN_METHOD";
const E_INVALID_ARGS: &str = "E_INVALID_ARGS";
const E_INVALID_REF: &str = "E_INVALID_REF";
const E_DUPLICATE_REF: &str = "E_DUPLICATE_REF";
const E_NOT_JOINED: &str = "E_NOT_JOINED";
const E_BUSINESS: &str = "E_BUSINESS";
const E_TRANSPORT: &str = "E_TRANSPORT";
const E_LIMIT: &str = "E_LIMIT";
const E_CANCELLED: &str = "E_CANCELLED";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn websocket_path_appends_the_phoenix_suffix() {
        let mut config = ChannelsGatewayConfig::new();
        assert_eq!(config.websocket_path(), "/socket/websocket");

        config.path = Cow::Borrowed("/rpc/");
        assert_eq!(config.websocket_path(), "/rpc/websocket");
    }

    #[test]
    fn valid_ref_accepts_the_documented_alphabet() {
        assert!(valid_ref("1"));
        assert!(valid_ref("call-1"));
        assert!(valid_ref("a.b_c:d"));
        assert!(valid_ref(&"a".repeat(64)));
    }

    #[test]
    fn valid_ref_rejects_empty_long_and_special_refs() {
        assert!(!valid_ref(""));
        assert!(!valid_ref(&"a".repeat(65)));
        assert!(!valid_ref("a/b"));
        assert!(!valid_ref("a b"));
        assert!(!valid_ref("a\n"));
    }

    #[test]
    fn call_request_requires_the_method() {
        assert!(CallRequest::parse(&json!({ "method": "m" })).is_ok());
        assert!(CallRequest::parse(&json!({ "method": "" })).is_err());
        assert!(CallRequest::parse(&json!({})).is_err());
    }

    #[test]
    fn call_request_defaults_args_to_null() {
        let request = CallRequest::parse(&json!({ "method": "m" })).expect("valid request");
        assert_eq!(request.args, Value::Null);
    }

    #[test]
    fn connection_state_limits_then_frees_a_slot() {
        let (state, _receiver) = ConnectionState::new(1, 1, PhoenixVersion::V2);
        state.join("Database");
        let first = state
            .admit("Database", "a")
            .expect("first call is admitted");
        assert!(matches!(
            state.admit("Database", "b"),
            Err(AdmissionError::Limit)
        ));

        state.finish("Database", "a");
        assert!(state.admit("Database", "b").is_ok());

        // The token of the finished call is not cancelled by `finish`.
        assert!(!first.is_cancelled());
    }

    #[test]
    fn connection_state_refuses_a_duplicate_ref() {
        let (state, _receiver) = ConnectionState::new(2, 1, PhoenixVersion::V2);
        state.join("Database");
        let _first = state
            .admit("Database", "a")
            .expect("first call is admitted");
        assert!(matches!(
            state.admit("Database", "a"),
            Err(AdmissionError::Duplicate)
        ));
    }

    #[test]
    fn connection_state_refuses_a_topic_that_was_not_joined() {
        let (state, _receiver) = ConnectionState::new(2, 1, PhoenixVersion::V2);
        assert!(matches!(
            state.admit("Database", "a"),
            Err(AdmissionError::NotJoined)
        ));
    }

    #[test]
    fn cancelling_one_call_does_not_cancel_its_neighbours() {
        let (state, _receiver) = ConnectionState::new(2, 1, PhoenixVersion::V2);
        state.join("Database");
        let first = state
            .admit("Database", "a")
            .expect("first call is admitted");
        let second = state
            .admit("Database", "b")
            .expect("second call is admitted");

        state.cancel("Database", "a");
        assert!(first.is_cancelled());
        assert!(!second.is_cancelled());
    }

    #[test]
    fn leaving_a_topic_only_cancels_that_topic() {
        let (state, _receiver) = ConnectionState::new(2, 1, PhoenixVersion::V2);
        state.join("Database");
        state.join("Billing");
        let database = state
            .admit("Database", "a")
            .expect("the database call is admitted");
        let billing = state
            .admit("Billing", "a")
            .expect("the billing call is admitted");

        state.leave("Database");
        assert!(database.is_cancelled());
        assert!(!billing.is_cancelled());
        assert!(!state.is_joined("Database"));
        assert!(state.is_joined("Billing"));
    }

    #[test]
    fn rejoining_a_topic_cancels_its_previous_calls() {
        let (state, _receiver) = ConnectionState::new(2, 1, PhoenixVersion::V2);
        state.join("Database");
        let previous = state
            .admit("Database", "a")
            .expect("the first call is admitted");

        state.join("Database");
        assert!(previous.is_cancelled());
        assert!(state.admit("Database", "a").is_ok(), "the table was reset");
    }

    #[test]
    fn shutdown_cancels_every_call_of_every_topic() {
        let (state, _receiver) = ConnectionState::new(2, 1, PhoenixVersion::V2);
        state.join("Database");
        state.join("Billing");
        let database = state
            .admit("Database", "a")
            .expect("the database call is admitted");
        let billing = state
            .admit("Billing", "a")
            .expect("the billing call is admitted");

        state.shutdown();
        assert!(database.is_cancelled());
        assert!(billing.is_cancelled());
        assert!(!state.is_joined("Database"));
        assert!(!state.is_joined("Billing"));
    }

    #[test]
    fn a_v2_reply_is_an_array_frame() {
        let (state, receiver) = ConnectionState::new(1, 2, PhoenixVersion::V2);
        let frame = PhoenixFrame {
            join_ref: Some("1".to_string()),
            reference: Some("2".to_string()),
            topic: "Database".to_string(),
            event: "call".to_string(),
            payload: json!({}),
        };

        crate::rt::test_block_on(state.reply(&frame, "ok", &json!({ "x": 1 })));
        let message = crate::rt::test_block_on(receiver.recv()).expect("a frame is queued");
        let value: Value =
            serde_json::from_str(message.to_text().expect("text")).expect("valid JSON");

        assert_eq!(value[0].as_str(), Some("1"));
        assert_eq!(value[1].as_str(), Some("2"));
        assert_eq!(value[2].as_str(), Some("Database"));
        assert_eq!(value[3].as_str(), Some("phx_reply"));
        assert_eq!(value[4]["status"].as_str(), Some("ok"));
        assert_eq!(value[4]["response"]["x"].as_u64(), Some(1));
    }

    #[test]
    fn origin_allowlist_is_exact() {
        let allowed = vec!["https://app.example.com".to_string()];
        assert!(origin_allowed("https://app.example.com", &allowed));
        assert!(!origin_allowed("https://evil.example.com", &allowed));
    }

    #[test]
    fn call_errors_map_to_the_stable_codes() {
        assert_eq!(
            map_call_error(&JsonCallError::InvalidArgs("x".to_string())).0,
            E_INVALID_ARGS
        );
        assert_eq!(
            map_call_error(&JsonCallError::Business("x".to_string())).0,
            E_BUSINESS
        );
        assert_eq!(
            map_call_error(&JsonCallError::Transport("x".to_string())).0,
            E_TRANSPORT
        );
    }

    struct DenyAuthorizer;

    impl ChannelsAuthorizer for DenyAuthorizer {
        fn authorize_join(&self, _context: &JoinContext<'_>) -> Result<(), String> {
            Err("denied".to_string())
        }
    }

    #[test]
    fn the_authorizer_receives_the_join_context() {
        let headers = Headers::new();
        let params = json!({ "token": "secret" });
        let context = JoinContext {
            headers: &headers,
            params: &params,
            peer_addr: None,
            service: "Database",
        };

        assert_eq!(context.param("token"), Some(&json!("secret")));
        assert_eq!(context.header("missing"), None);
        assert_eq!(context.service(), "Database");
        assert_eq!(
            DenyAuthorizer.authorize_join(&context),
            Err("denied".to_string())
        );
    }
}
